CSS += '''.so-reference-actions{display:grid;grid-template-columns:minmax(0,1fr);gap:12px;margin:20px 0 24px}.so-reference-actions button{display:flex;align-items:center;width:100%;min-height:48px;padding:13px 16px;border:1px solid #b9cde9;border-radius:8px;background:#edf4ff;color:#13346f;text-align:left;font:inherit;font-weight:600;line-height:1.5;white-space:normal;overflow-wrap:anywhere;transition:background .15s,border-color .15s}.so-reference-actions button:hover:not(:disabled){background:#dfeaff;border-color:#0a369d}.so-reference-actions button:focus-visible{outline:3px solid #548bed;outline-offset:3px}.so-reference-actions button:disabled{opacity:.6;cursor:wait}'''
